# Replace static access + unsafe bank loading with dynamic permission-aware flow.
start=s.index('async function init(){')
end=s.index('\nconst UNIVERSAL_COLUMN_PREF_PREFIX',start)
access_block=r'''async function init(){loginBtn.onclick=signInWithPassword;signupBtn.onclick=firstUseSignup;logoutBtn.onclick=async()=>{await sb.auth.signOut();location.reload()};document.querySelectorAll(".nav").forEach(b=>b.onclick=()=>openPage(b.dataset.page,b.textContent));const {data:{session:s}}=await sb.auth.getSession();session=s;sb.auth.onAuthStateChange(async(_e,s2)=>{session=s2;if(s2)await enterApp();else showAuth()});if(session)await enterApp();else showAuth()}
function showAuth(){authScreen.classList.remove("hidden");app.classList.add("hidden")}
async function loadMyPermissions(){const {data,error}=await sb.rpc('get_my_permissions');if(error){console.error(error);permissionMap={};return}permissionMap=Object.fromEntries((data||[]).map(x=>[x.permission_key,!!x.allowed]))}
function canPage(id){const k=`page.${id}`;return Object.prototype.hasOwnProperty.call(permissionMap,k)?permissionMap[k]:(PAGE_ACCESS[profile?.role]||[]).includes(id)}
function canBankBalances(){return Object.prototype.hasOwnProperty.call(permissionMap,'data.bank_balances')?permissionMap['data.bank_balances']:['CFO','Supervisor','BankAccountant'].includes(profile?.role)}
async function enterApp(){const {data:u}=await sb.from("profiles").select("*").eq("id",session.user.id).maybeSingle();if(!u){showAuth();loginMsg.textContent=displayText("الحساب غير مصرح أو لم يكتمل إنشاؤه.");return}profile=u;await loadMyPermissions();authScreen.classList.add("hidden");app.classList.remove("hidden");userRole.textContent=`${profile.full_name} — ${displayText(ROLE_LABEL[profile.role]||profile.role)}`;applyAccess();await reloadAll();if(!canPage('dashboard')){const first=[...document.querySelectorAll('.nav')].find(b=>!b.classList.contains('hidden'));if(first)openPage(first.dataset.page,first.textContent)}applyLanguage()}
function applyAccess(){document.querySelectorAll(".nav").forEach(b=>b.classList.toggle("hidden",!canPage(b.dataset.page)));document.querySelectorAll('.nav-group').forEach(g=>{const any=[...g.querySelectorAll('.nav')].some(b=>!b.classList.contains('hidden'));g.classList.toggle('hidden',!any)});addBankBtn.classList.toggle("hidden",!["CFO","Supervisor","BankAccountant"].includes(profile.role)||!canBankBalances());addPaymentBtn.classList.toggle("hidden",!["CFO","Supervisor","BankAccountant","APAccountant"].includes(profile.role));paymentReportBtn.classList.toggle("hidden",!["CFO","Supervisor","BankAccountant"].includes(profile.role));addTaskBtn.classList.toggle("hidden",!["CFO","Supervisor"].includes(profile.role));dailyPlanBtn.classList.toggle("hidden",!["Supervisor","CFO"].includes(profile.role));capacityBtn?.classList.toggle("hidden",!["CFO","Supervisor"].includes(profile.role));addExceptionBtn.classList.toggle("hidden",profile.role!=="CFO");addPolicyBtn?.classList.toggle("hidden",profile.role!=="CFO");addCloseBtn.classList.toggle("hidden",!["CFO","Supervisor"].includes(profile.role));addImprestBtn.classList.toggle("hidden",!["CFO","Supervisor","BankAccountant","APAccountant"].includes(profile.role))}
function openPage(id,title){if(!canPage(id))return;document.querySelectorAll(".section").forEach(x=>x.classList.remove("active"));document.getElementById(id)?.classList.add("active");document.querySelectorAll(".nav").forEach(x=>x.classList.remove("active"));document.querySelector(`.nav[data-page="${id}"]`)?.classList.add("active");pageTitle.textContent=title;if(id==="audit")loadAudit();if(id==='permissions')loadPermissionsAdmin()}
async function reloadAll(){
 const core=[sb.from("profiles").select("id,email,full_name,role").eq("active",true),sb.rpc('get_bank_account_directory'),sb.from("payments").select("*").order("created_at",{ascending:false}),sb.from("tasks").select("*,owner:profiles!tasks_owner_id_fkey(full_name),reviewer:profiles!tasks_reviewer_id_fkey(full_name)").order("due_date",{ascending:false}).order("created_at",{ascending:false}),sb.from("exceptions").select("*,owner:profiles!exceptions_owner_id_fkey(full_name),leave_delegations(*,absent:profiles!leave_delegations_absent_user_id_fkey(full_name),substitute:profiles!leave_delegations_substitute_user_id_fkey(full_name))").order("created_at",{ascending:false}),sb.from("monthly_close_tasks").select("*,owner:profiles!monthly_close_tasks_owner_id_fkey(full_name)").order("due_date").order("code"),sb.from("imprest_funds").select("*,custodian:profiles!imprest_funds_custodian_id_fkey(full_name)").order("created_at",{ascending:false}),sb.rpc("get_finance_team_performance"),sb.from("ownership_matrix").select("*").order("sort_order")];
 const [pr,dir,py,tk,ex,cl,im,pf,ow]=await Promise.all(core);profiles=pr.data||[];bankDirectory=dir.data||[];payments=(py.data||[]).map(x=>({...x,bank_accounts:bankDirectory.find(b=>b.id===x.bank_account_id)||null}));tasks=tk.data||[];exceptions=ex.data||[];closeTasks=cl.data||[];imprest=im.data||[];performance=pf.data||[];ownership=ow.data||[];
 if(canBankBalances()){const [bk,rr]=await Promise.all([sb.rpc('get_visible_bank_liquidity'),sb.rpc("get_reserve_account_monitor")]);banks=bk.data||[];reserveAccounts=rr.data||[]}else{banks=[];reserveAccounts=[]}
 const pol=await sb.rpc("get_finance_policy_register");financePolicies=pol.data||[];
 if(["CFO","Supervisor"].includes(profile.role)){const req=[sb.rpc("get_supervisor_control_center"),sb.rpc("get_workload_capacity"),sb.rpc("get_escalation_center")];if(canPage('automation'))req.push(sb.rpc("get_automation_health"));const out=await Promise.all(req);controlCenter=out[0].data||[];workload=out[1].data||[];escalations=out[2].data||[];automationHealth=canPage('automation')?(out[3]?.data||[]):[]}else{controlCenter=[];workload=[];escalations=[];automationHealth=[]}
 if(["CFO","Supervisor","GLAccountant"].includes(profile.role)){const q=await sb.rpc('get_payment_accounting_queue');paymentQueue=q.data||[]}else paymentQueue=[];
 renderAll()
}
'''
s=s[:start]+access_block+s[end:]

# Replace manual daily plan: only templates selected explicitly + new ad-hoc task/template.
start=s.index('async function openDailyPlan(){')
end=s.index('\nasync function startTask',start)
manual_plan=r'''async function openDailyPlan(){
 if(!["Supervisor","CFO"].includes(profile.role))return;
 const {data:catalog,error}=await sb.from('finance_task_catalog').select('id,name,default_owner_id,default_priority,output').eq('active',true).order('name');if(error)return alert(error.message);
 const owners=profiles.map(x=>({value:x.id,label:x.full_name}));
 const rows=(catalog||[]).map(t=>`<tr><td><input type="checkbox" class="plan-template-check" data-id="${t.id}"></td><td style="white-space:normal">${esc(t.name)}</td><td>${selectInline('plan-template-owner',t.id,owners,t.default_owner_id||'')}</td><td>${selectInline('plan-template-priority',t.id,['عادي','عالي','حرج'],t.default_priority||'عادي')}</td><td><input type="time" class="plan-template-time" data-id="${t.id}" value="09:00"></td><td style="white-space:normal">${esc(t.output||'—')}</td></tr>`).join('');
 showModal(displayText('خطة اليوم / فتح المهام'),`<div class="note">${displayText('المهام الافتراضية لا تفتح تلقائيًا. اختر يدويًا من القوالب أو أضف مهمة جديدة.')}</div><div class="row" style="margin:12px 0"><h4 style="margin:0">${displayText('قوالب المهام')}</h4><button class="btn" onclick="openTaskTemplateModal()">+ ${displayText('إضافة قالب جديد')}</button></div><div class="table-wrap"><table><thead><tr><th></th><th>${displayText('المهمة')}</th><th>${displayText('المسؤول')}</th><th>${displayText('الأولوية')}</th><th>${displayText('الوقت')}</th><th>${displayText('المخرج')}</th></tr></thead><tbody>${rows||'<tr><td colspan="6">—</td></tr>'}</tbody></table></div><h4>${displayText('مهمة جديدة لليوم')}</h4><div class="modal-grid">${input('plan_new_name','المهمة')}${select('plan_new_owner','المسؤول',[{value:'',label:'—'},...owners])}${select('plan_new_priority','الأولوية',['عادي','عالي','حرج'])}${input('plan_new_time','الوقت','09:00','time')}${input('plan_new_output','المخرج')}</div><label style="margin-top:10px;display:flex;align-items:center;gap:7px"><input id="plan_save_template" type="checkbox" style="width:auto"> ${displayText('حفظ كقالب')}</label><div class="row" style="margin-top:14px"><button class="btn primary" onclick="saveDailyPlan()">${displayText('فتح المهام المحددة')}</button></div>`);installTableFilters();applyLanguage(document.getElementById('modalBody'))
}
async function openTaskTemplateModal(){const name=prompt(currentLang==='en'?'Template name:':'اسم القالب:');if(!name||!name.trim())return;const owner=prompt(currentLang==='en'?'Paste owner ID from the team list shown in Daily Plan.':'أدخل معرف الموظف المسؤول من بيانات الفريق.');if(!owner)return;const {error}=await sb.rpc('create_finance_task_template',{p_name:name.trim(),p_owner_id:owner,p_priority:'عادي',p_output:null});if(error)return alert(error.message);closeModal();await openDailyPlan()}
async function saveDailyPlan(){const items=[];document.querySelectorAll('.plan-template-check:checked').forEach(c=>{const id=c.dataset.id;items.push({catalog_id:id,owner_id:document.querySelector(`.plan-template-owner[data-id="${id}"]`)?.value||'',priority:document.querySelector(`.plan-template-priority[data-id="${id}"]`)?.value||'عادي',due_time:document.querySelector(`.plan-template-time[data-id="${id}"]`)?.value||''})});const name=(val('plan_new_name')||'').trim();if(name)items.push({name,owner_id:val('plan_new_owner'),priority:val('plan_new_priority')||'عادي',due_time:val('plan_new_time'),output:val('plan_new_output')||null,save_as_template:!!document.getElementById('plan_save_template')?.checked});if(!items.length)return alert(currentLang==='en'?'Select a template or add a new task.':'اختر قالبًا أو أضف مهمة جديدة.');if(items.some(x=>!x.owner_id||!x.due_time))return alert(currentLang==='en'?'Owner and due time are required.':'يجب تحديد المسؤول ووقت الاستحقاق.');const {data,error}=await sb.rpc('save_manual_daily_plan',{p_items:items});if(error)return alert(error.message);closeModal();await reloadAll();alert(currentLang==='en'?`${data||0} tasks opened.`:`تم فتح ${data||0} مهمة ضمن خطة اليوم.`)}
'''
s=s[:start]+manual_plan+s[end:]

# Payment action authority: Fahad registration/post/pending; CFO override any stage.
start=s.index('function paymentActions(p){')
end=s.index('\nasync function deleteRequestedPayment',start)
payment_actions=r'''function paymentActions(p){let a=[];if(((profile.role==="CFO")||(["Supervisor","BankAccountant"].includes(profile.role)&&p.cfo_status!=="موافق"))&&!p.executed_at&&!p.posted_at&&p.status!=="مرحّل")a.push(`<button class="btn" onclick="openPaymentModal('${p.id}')">${displayText('تعديل')}</button>`);if(profile.role==="Supervisor"&&p.supervisor_status==="معلق")a.push(`<button class="btn success" onclick="supervisorApprove('${p.id}')">${displayText('اعتماد المشرف')}</button>`);if(profile.role==="CFO"&&p.supervisor_status==="موافق"&&p.cfo_status==="معلق")a.push(`<button class="btn success" onclick="cfoApprove('${p.id}')">${displayText('اعتماد CFO')}</button>`);if(profile.role==="BankAccountant"&&p.cfo_status==="موافق"&&!p.executed_at)a.push(`<button class="btn success" onclick="executePayment('${p.id}')">${displayText('تم التنفيذ')}</button>`);if(profile.role==="GLAccountant"&&p.status==="منفذ"&&p.executed_at&&!p.posted_at)a.push(`<button class="btn success" onclick="registerPaymentAccounting('${p.id}')">${displayText('تم التسجيل')}</button>`);if(["Supervisor","CFO","GLAccountant"].includes(profile.role)&&p.status==="تم التسجيل"&&!p.posted_at){a.push(`<button class="btn success" onclick="finalizeRegisteredPayment('${p.id}','Posted')">${displayText('مرحّل')}</button>`);a.push(`<button class="btn" onclick="openPendingPaymentModal('${p.id}')">${displayText('معلقة')}</button>`)}if(profile.role==='CFO')a.push(`<button class="btn" onclick="openCfoStatusOverride('${p.id}')">${displayText('تغيير الحالة بواسطة CFO')}</button>`);if(["CFO","Supervisor","BankAccountant"].includes(profile.role)&&!p.executed_at&&!p.posted_at&&p.status!=="مرحّل")a.push(`<button class="btn danger" onclick="deleteRequestedPayment('${p.id}')">${displayText('حذف')}</button>`);return a.join(" ")||"—"}
function pendingPaymentActions(p){const a=[];if(["Supervisor","CFO","GLAccountant"].includes(profile.role))a.push(`<button class="btn success" onclick="finalizeRegisteredPayment('${p.id}','Posted')">${displayText('مرحّل')}</button>`);if(profile.role==='CFO')a.push(`<button class="btn" onclick="openCfoStatusOverride('${p.id}')">${displayText('تغيير الحالة بواسطة CFO')}</button>`);return a.join(' ')||'—'}
async function registerPaymentAccounting(id){const {error}=await sb.rpc('register_payment_accounting',{p_payment_id:id});if(error)return alert(error.message);await reloadAll()}
function openPendingPaymentModal(id){if(!["Supervisor","CFO","GLAccountant"].includes(profile.role))return;const p=payments.find(x=>x.id===id);if(!p)return;showModal(displayText('تعليق العملية'),`<div class="note">${esc(p.company)} — ${esc(p.beneficiary)} — ${moneyHtml(p.amount)}</div><label style="margin-top:10px">${displayText('سبب التعليق / التبرير')} *</label><textarea id="pend_reason" rows="4"></textarea><div class="modal-grid" style="margin-top:10px">${input('pend_action','الإجراء المطلوب')}${select('pend_owner','مسؤول المتابعة',[{value:'',label:'—'},...profiles.map(x=>({value:x.id,label:x.full_name}))])}${input('pend_follow','تاريخ المتابعة','','date')}</div><div class="row" style="margin-top:14px"><button class="btn primary" onclick="savePendingPayment('${id}')">${displayText('حفظ')}</button></div>`)}
async function savePendingPayment(id){const reason=(val('pend_reason')||'').trim();if(!reason)return alert(displayText('سبب التعليق إلزامي.'));const {error}=await sb.rpc('supervisor_finalize_registered_payment',{p_payment_id:id,p_action:'Pending',p_reason:reason,p_pending_action:val('pend_action')||null,p_pending_owner_id:val('pend_owner')||null,p_follow_up_date:val('pend_follow')||null});if(error)return alert(error.message);closeModal();await reloadAll();openPage('pending',displayText('العمليات المعلقة'))}
async function finalizeRegisteredPayment(id,action){if(!["Supervisor","CFO","GLAccountant"].includes(profile.role))return;const {error}=await sb.rpc('supervisor_finalize_registered_payment',{p_payment_id:id,p_action:action,p_reason:null,p_pending_action:null,p_pending_owner_id:null,p_follow_up_date:null});if(error)return alert(error.message);await reloadAll()}
function openCfoStatusOverride(id){if(profile.role!=='CFO')return;const p=payments.find(x=>x.id===id);if(!p)return;showModal(displayText('تغيير الحالة بواسطة CFO'),`${select('cfo_override_status','حالة جديدة',['بانتظار مراجعة المشرف','بانتظار اعتماد CFO','معتمد للدفع','منفذ','تم التسجيل','معلقة','مرحّل','مرفوض','موقوف'],p.status)}<label style="margin-top:10px">${displayText('سبب التغيير')} *</label><textarea id="cfo_override_reason" rows="3"></textarea><div class="row" style="margin-top:14px"><button class="btn primary" onclick="saveCfoStatusOverride('${id}')">${displayText('حفظ')}</button></div>`)}
async function saveCfoStatusOverride(id){const reason=(val('cfo_override_reason')||'').trim();if(!reason)return alert(currentLang==='en'?'Change reason is required.':'سبب التغيير إلزامي.');const {error}=await sb.rpc('cfo_override_payment_status',{p_payment_id:id,p_status:val('cfo_override_status'),p_reason:reason});if(error)return alert(error.message);closeModal();await reloadAll()}
'''
s=s[:start]+payment_actions+s[end:]

# Performance includes operational activity and report tools.
old="function renderPerformance(){performanceBody.innerHTML=performance.map(x=>`<tr><td>${esc(x.full_name||\"—\")}</td><td>${esc(displayText(ROLE_LABEL[x.role]||x.role||\"\"))}</td><td>${Number(x.today_total||0)}</td><td>${Number(x.today_completed||0)}</td><td>${Number(x.today_overdue||0)}</td><td>${Number(x.pending_justifications||0)}</td><td>${Number(x.pending_review||0)}</td><td><button class=\"link-metric\" onclick=\"openPerformanceDrilldown('${x.user_id}','month')\">${Number(x.month_completion_rate||0).toFixed(1)}%</button></td><td><button class=\"link-metric\" onclick=\"openPerformanceDrilldown('${x.user_id}','ontime')\">${Number(x.tracked_on_time_rate||0).toFixed(1)}%</button></td><td><button class=\"link-metric\" onclick=\"openPerformanceDrilldown('${x.user_id}','close')\">${Number(x.close_completion_rate||0).toFixed(1)}%</button></td></tr>`).join(\"\")||`<tr><td colspan=\"10\" class=\"muted\">${displayText('لا توجد بيانات أداء بعد.')}</td></tr>`}"
new="function renderPerformance(){performanceBody.innerHTML=performance.map(x=>`<tr><td>${esc(x.full_name||\"—\")}</td><td>${esc(displayText(ROLE_LABEL[x.role]||x.role||\"\"))}</td><td>${Number(x.today_total||0)}</td><td>${Number(x.today_completed||0)}</td><td>${Number(x.today_overdue||0)}</td><td>${Number(x.pending_justifications||0)}</td><td>${Number(x.pending_review||0)}</td><td><button class=\"link-metric\" onclick=\"openPerformanceDrilldown('${x.user_id}','month')\">${Number(x.month_completion_rate||0).toFixed(1)}%</button></td><td><button class=\"link-metric\" onclick=\"openPerformanceDrilldown('${x.user_id}','ontime')\">${Number(x.tracked_on_time_rate||0).toFixed(1)}%</button></td><td><button class=\"link-metric\" onclick=\"openPerformanceDrilldown('${x.user_id}','close')\">${Number(x.close_completion_rate||0).toFixed(1)}%</button></td><td>${Number(x.today_operational_activities||0)}</td><td>${Number(x.month_operational_activities||0)}</td><td>${Number(x.payment_sla_overdue||0)}</td></tr>`).join(\"\")||`<tr><td colspan=\"13\" class=\"muted\">${displayText('لا توجد بيانات أداء بعد.')}</td></tr>`}"
assert old in s,'renderPerformance not found';s=s.replace(old,new,1)

insert_before='function remainingText(m)'
kpi_funcs=r'''let kpiReportRows=[];
function openKpiReport(){if(!['CFO','Supervisor'].includes(profile.role))return;const d=new Date(),to=d.toISOString().slice(0,10),from=new Date(d.getFullYear(),d.getMonth(),1).toISOString().slice(0,10);showModal(displayText('تقرير KPI / الأداء'),`<div class="modal-grid">${input('kpi_from','من',from,'date')}${input('kpi_to','إلى',to,'date')}</div><div class="report-toolbar" style="margin-top:12px"><button class="btn primary" onclick="previewKpiReport()">${displayText('معاينة')}</button><button class="btn" onclick="exportKpiCsv()">${displayText('تصدير CSV')}</button><button class="btn" onclick="printKpiReport()">${displayText('طباعة / PDF')}</button></div><div id="kpiReportOutput"></div>`);previewKpiReport()}
async function previewKpiReport(){const {data,error}=await sb.rpc('get_finance_team_kpi_report',{p_from:val('kpi_from')||null,p_to:val('kpi_to')||null});const out=document.getElementById('kpiReportOutput');if(error){out.innerHTML=`<div class="warning-box">${esc(error.message)}</div>`;return}kpiReportRows=data||[];out.innerHTML=`<div class="table-wrap"><table><thead><tr><th>${displayText('الموظف')}</th><th>${displayText('الدور')}</th><th>${displayText('المهام')}</th><th>${displayText('مكتمل')}</th><th>${displayText('الإنجاز')}</th><th>${displayText('الإنجاز في الموعد')}</th><th>${displayText('نشاط الشهر')}</th><th>${displayText('تجاوز SLA')}</th></tr></thead><tbody>${kpiReportRows.map(x=>`<tr><td>${esc(x.full_name)}</td><td>${esc(displayText(ROLE_LABEL[x.role]||x.role))}</td><td>${x.assigned_tasks}</td><td>${x.completed_tasks}</td><td>${Number(x.completion_rate||0).toFixed(1)}%</td><td>${Number(x.on_time_rate||0).toFixed(1)}%</td><td>${x.operational_activities}</td><td>${x.sla_overdue_activities}</td></tr>`).join('')}</tbody></table></div>`;installTableFilters();applyLanguage(out)}
function kpiCsvRows(){return [['Employee','Role','Assigned Tasks','Completed Tasks','Completion Rate','On Time Rate','Operational Activities','SLA Overdue'],...kpiReportRows.map(x=>[x.full_name,x.role,x.assigned_tasks,x.completed_tasks,x.completion_rate,x.on_time_rate,x.operational_activities,x.sla_overdue_activities])]}
async function exportKpiCsv(){await previewKpiReport();const lines=kpiCsvRows().map(r=>r.map(csvCell).join(',')).join('\r\n'),blob=new Blob(['﻿'+lines],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Sanam_Team_KPI.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),100)}
async function printKpiReport(){await previewKpiReport();const rows=kpiCsvRows(),w=window.open('','_blank');if(!w)return;w.document.write(`<!doctype html><html dir="${currentLang==='en'?'ltr':'rtl'}"><head><meta charset="utf-8"><style>body{font-family:Segoe UI,Tahoma,Arial}table{width:100%;border-collapse:collapse;font-size:11px}th,td{border:1px solid #ddd;padding:6px}</style></head><body><h2>Sanam Finance Portal — ${displayText('تقرير KPI / الأداء')}</h2><table><thead><tr>${rows[0].map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.slice(1).map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></body></html>`);w.document.close();setTimeout(()=>w.print(),200)}
'''
pos=s.index(insert_before);s=s[:pos]+kpi_funcs+s[pos:]

