queue_func=r'''function renderAccountingQueue(){const panel=document.getElementById('accountingQueuePanel');if(!panel)return;const allowed=['CFO','Supervisor','GLAccountant'].includes(profile.role);panel.classList.toggle('hidden',!allowed);if(!allowed)return;const overdue=paymentQueue.filter(x=>x.sla_status==='Overdue').length,due=paymentQueue.filter(x=>x.sla_status==='Due Soon').length;accountingQueueSummary.innerHTML=`<div class="card"><span class="muted">${displayText('عدد الدفعات')}</span><b>${paymentQueue.length}</b></div><div class="card"><span class="muted">${displayText('متجاوز المهلة')}</span><b>${overdue}</b></div><div class="card"><span class="muted">${displayText('قرب انتهاء المهلة')}</span><b>${due}</b></div>`;accountingQueueBody.innerHTML=paymentQueue.map(q=>{const p=payments.find(x=>x.id===q.payment_id);const cls=q.sla_status==='Overdue'?'sla-overdue':q.sla_status==='Due Soon'?'sla-due':'sla-ok';const label=q.sla_status==='Overdue'?'متجاوز المهلة':q.sla_status==='Due Soon'?'قرب انتهاء المهلة':'داخل المهلة';return `<tr class="${q.sla_status==='Overdue'?'task-overdue':''}"><td>${fmt(q.executed_at)}</td><td>${esc(q.company)}</td><td>${esc(q.beneficiary)}</td><td>${moneyHtml(q.amount)}</td><td>${badge(q.status)}</td><td><span class="badge ${cls}">${displayText(label)}</span></td><td>${q.hours_remaining<0?`${Math.abs(Number(q.hours_remaining)).toFixed(1)}h ${displayText('متأخر')}`:`${Number(q.hours_remaining).toFixed(1)}h`}</td><td>${p?paymentActions(p):'—'}</td></tr>`}).join('')||'<tr><td colspan="8">—</td></tr>';applyTableFilters(document.getElementById('accountingQueueTable'))}
'''
