perm_funcs=r'''const PERMISSION_KEYS=[['page.dashboard','لوحة المعلومات'],['page.banks','السيولة والبنوك'],['page.payments','المدفوعات والاعتمادات'],['page.posted','المدفوعات المرحلة'],['page.pending','العمليات المعلقة'],['page.tasks','المهام'],['page.control','مركز التحكم اليومي'],['page.escalations','التعثر والتصعيد'],['page.automation','صحة الأتمتة'],['page.close','الإقفال الشهري'],['page.imprest','العهد'],['page.performance','أداء الفريق'],['page.ownership','مصفوفة المسؤوليات'],['page.exceptions','الاستثناءات والإجازات'],['page.audit','سجل العمليات'],['data.bank_balances','بيانات الأرصدة البنكية']];
async function loadPermissionsAdmin(){if(profile.role!=='CFO')return;const {data,error}=await sb.from('user_permissions').select('user_id,permission_key,allowed');if(error)return alert(error.message);const m=new Map((data||[]).map(x=>[`${x.user_id}:${x.permission_key}`,!!x.allowed]));permissionsMatrix.innerHTML=`<table><thead><tr><th>${displayText('الموظف')}</th><th>${displayText('الدور')}</th>${PERMISSION_KEYS.map(x=>`<th>${displayText(x[1])}</th>`).join('')}</tr></thead><tbody>${profiles.map(u=>`<tr><td>${esc(u.full_name)}</td><td>${esc(displayText(ROLE_LABEL[u.role]||u.role))}</td>${PERMISSION_KEYS.map(([k])=>{const locked=['page.dashboard','page.banks','data.bank_balances'].includes(k)&&!['CFO','Supervisor','BankAccountant'].includes(u.role);const checked=locked?false:(m.get(`${u.id}:${k}`)??false);return `<td class="${locked?'permission-lock':''}"><input type="checkbox" ${checked?'checked':''} ${locked?'disabled':''} onchange="setPermissionAdmin('${u.id}','${k}',this.checked)"></td>`}).join('')}</tr>`).join('')}</tbody></table>`;installTableFilters();applyLanguage(permissionsMatrix)}
async function setPermissionAdmin(userId,key,allowed){const {error}=await sb.rpc('set_user_permission',{p_user_id:userId,p_permission_key:key,p_allowed:allowed});if(error){alert(error.message);await loadPermissionsAdmin();return}if(userId===profile.id){await loadMyPermissions();applyAccess()}await loadPermissionsAdmin()}
'''
